import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { getCard, updateCard } from '../services/api';

const EditCard = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const [formData, setFormData] = useState({
    title: '',
    trait: '',
    isToken: false,
    rarity: '',
    class: '',
    unevolvedDescription: '',
    evolvedDescription: '',
    image: null
  });
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchCard = async () => {
      try {
        const card = await getCard(id);
        setFormData({
          title: card.title,
          trait: card.trait || '',
          isToken: card.isToken || false,
          rarity: card.rarity,
          class: card.class,
          unevolvedDescription: card.unevolvedDescription,
          evolvedDescription: card.evolvedDescription,
          image: null
        });
        setPreview(card.imageUrl);
        setLoading(false);
      } catch (err) {
        setError('Failed to fetch card details. Please try again later.');
        setLoading(false);
      }
    };

    fetchCard();
  }, [id]);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === 'checkbox' ? checked : value
    });
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFormData({
        ...formData,
        image: file
      });
      
      // Create a preview URL for the selected image
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!formData.title || !formData.rarity || !formData.class || 
        !formData.unevolvedDescription || !formData.evolvedDescription) {
      setError('Please fill in all required fields.');
      return;
    }
    
    setSubmitting(true);
    setError(null);
    
    try {
      const data = new FormData();
      data.append('title', formData.title);
      data.append('trait', formData.trait);
      data.append('isToken', formData.isToken);
      data.append('rarity', formData.rarity);
      data.append('class', formData.class);
      data.append('unevolvedDescription', formData.unevolvedDescription);
      data.append('evolvedDescription', formData.evolvedDescription);
      
      if (formData.image) {
        data.append('image', formData.image);
      }
      
      await updateCard(id, data);
      navigate('/');
    } catch (err) {
      setError('Failed to update card. Please try again.');
      setSubmitting(false);
    }
  };

  // Rarity options
  const rarityOptions = ['Bronze', 'Silver', 'Gold', 'Legendary'];
  
  // Class options
  const classOptions = [
    'Neutral', 'Forestcraft', 'Swordcraft', 'Runecraft', 
    'Dragoncraft', 'Shadowcraft', 'Bloodcraft', 'Havencraft', 
    'Portalcraft'
  ];

  if (loading) {
    return <div className="loading">Loading card details...</div>;
  }

  return (
    <div className="edit-card-page">
      <div className="header">
        <h1>Edit Card</h1>
      </div>
      
      <form className="create-card-form" onSubmit={handleSubmit}>
        <h2 className="form-title">Update Card Details</h2>
        
        {error && <div className="error">{error}</div>}
        
        <div className="form-group">
          <label htmlFor="title">Title *</label>
          <input
            type="text"
            id="title"
            name="title"
            className="form-control"
            value={formData.title}
            onChange={handleChange}
            placeholder="Enter card title"
            required
          />
        </div>
        
        <div className="form-row">
          <div className="form-group">
            <label htmlFor="trait">Trait (Optional)</label>
            <input
              type="text"
              id="trait"
              name="trait"
              className="form-control"
              value={formData.trait}
              onChange={handleChange}
              placeholder="Enter card trait"
            />
          </div>
          
          <div className="form-group checkbox-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                name="isToken"
                checked={formData.isToken}
                onChange={handleChange}
              />
              Token Card
            </label>
          </div>
        </div>
        
        <div className="form-row">
          <div className="form-group">
            <label htmlFor="rarity">Rarity *</label>
            <select
              id="rarity"
              name="rarity"
              className="form-control"
              value={formData.rarity}
              onChange={handleChange}
              required
            >
              <option value="">Select Rarity</option>
              {rarityOptions.map(option => (
                <option key={option} value={option}>{option}</option>
              ))}
            </select>
          </div>
          
          <div className="form-group">
            <label htmlFor="class">Class *</label>
            <select
              id="class"
              name="class"
              className="form-control"
              value={formData.class}
              onChange={handleChange}
              required
            >
              <option value="">Select Class</option>
              {classOptions.map(option => (
                <option key={option} value={option}>{option}</option>
              ))}
            </select>
          </div>
        </div>
        
        <div className="form-group">
          <label htmlFor="unevolvedDescription">Unevolved Description *</label>
          <textarea
            id="unevolvedDescription"
            name="unevolvedDescription"
            className="form-control"
            value={formData.unevolvedDescription}
            onChange={handleChange}
            placeholder="Enter unevolved card description"
            rows="4"
            required
          ></textarea>
          <small className="form-text">
            Press Enter for line breaks. They will be preserved in the card view.
          </small>
        </div>
        
        <div className="form-group">
          <label htmlFor="evolvedDescription">Evolved Description *</label>
          <textarea
            id="evolvedDescription"
            name="evolvedDescription"
            className="form-control"
            value={formData.evolvedDescription}
            onChange={handleChange}
            placeholder="Enter evolved card description"
            rows="4"
            required
          ></textarea>
          <small className="form-text">
            Press Enter for line breaks. They will be preserved in the card view.
          </small>
        </div>
        
        <div className="form-group">
          <label htmlFor="image">Card Image (Optional)</label>
          <input
            type="file"
            id="image"
            name="image"
            className="form-control"
            accept="image/*"
            onChange={handleImageChange}
          />
          <small className="form-text text-muted">Leave empty to keep the current image</small>
        </div>
        
        <div className="image-preview">
          {preview ? (
            <img src={preview} alt="Preview" />
          ) : (
            <span className="image-preview-text">No image selected</span>
          )}
        </div>
        
        <div className="form-actions">
          <button 
            type="button" 
            className="btn btn-secondary"
            onClick={() => navigate('/')}
          >
            Cancel
          </button>
          <button 
            type="submit" 
            className="btn submit-btn"
            disabled={submitting}
          >
            {submitting ? 'Updating...' : 'Update Card'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default EditCard;
